window.SFT = {"duration":279.1,"groups":[{"id":"title","n":1,"section":1,"title":true,"first":0.05,"end":3.35,"caps":[{"text":"What if sound travelled faster than light?","show":0.05,"hide":3.35,"words":[{"text":"What","start":0.05},{"text":"if","start":0.38},{"text":"sound","start":0.71},{"text":"travelled","start":1.04},{"text":"faster","start":1.37},{"text":"than","start":1.7},{"text":"light?","start":2.03}]}]},{"id":"start","n":2,"section":1,"title":false,"first":4.25,"end":20.8,"caps":[{"text":"8:52 PM, on a corn farm in Iowa. Your daughter just ran into the corn after the dog.","show":4.25,"hide":9.45,"words":[{"text":"8:52","start":4.25},{"text":"PM,","start":4.452},{"text":"on","start":4.654},{"text":"a","start":4.857},{"text":"corn","start":5.059},{"text":"farm","start":5.261},{"text":"in","start":5.463},{"text":"Iowa.","start":5.666},{"text":"Your","start":5.868},{"text":"daughter","start":6.07},{"text":"just","start":6.272},{"text":"ran","start":6.474},{"text":"into","start":6.677},{"text":"the","start":6.879},{"text":"corn","start":7.081},{"text":"after","start":7.283},{"text":"the","start":7.486},{"text":"dog.","start":7.688}]},{"text":"And sound just started travelling at 1 million km a second.","show":10.45,"hide":14.4,"words":[{"text":"And","start":10.45},{"text":"sound","start":10.701},{"text":"just","start":10.953},{"text":"started","start":11.204},{"text":"travelling","start":11.455},{"text":"at","start":11.707},{"text":"1","start":11.958},{"text":"million","start":12.21},{"text":"km","start":12.461},{"text":"a","start":12.712},{"text":"second.","start":12.964}]},{"text":"9 thunderclaps, still crawling across the fields towards you, hit you in the same instant.","show":15.4,"hide":20.8,"words":[{"text":"9","start":15.4},{"text":"thunderclaps,","start":15.652},{"text":"still","start":15.904},{"text":"crawling","start":16.156},{"text":"across","start":16.408},{"text":"the","start":16.66},{"text":"fields","start":16.912},{"text":"towards","start":17.164},{"text":"you,","start":17.416},{"text":"hit","start":17.668},{"text":"you","start":17.92},{"text":"in","start":18.172},{"text":"the","start":18.424},{"text":"same","start":18.676},{"text":"instant.","start":18.928}]}]},{"id":"flash","n":3,"section":1,"title":false,"first":22.2,"end":37.65,"caps":[{"text":"Thunder used to crawl behind the lightning at 343 m/s: 3 seconds for every kilometre.","show":22.2,"hide":27.45,"words":[{"text":"Thunder","start":22.2},{"text":"used","start":22.445},{"text":"to","start":22.69},{"text":"crawl","start":22.935},{"text":"behind","start":23.18},{"text":"the","start":23.425},{"text":"lightning","start":23.67},{"text":"at","start":23.915},{"text":"343","start":24.16},{"text":"m/s:","start":24.405},{"text":"3","start":24.65},{"text":"seconds","start":24.895},{"text":"for","start":25.14},{"text":"every","start":25.385},{"text":"kilometre.","start":25.63}]},{"text":"Now it comes with the flash.","show":28.85,"hide":31.25,"words":[{"text":"Now","start":28.85},{"text":"it","start":29.13},{"text":"comes","start":29.41},{"text":"with","start":29.69},{"text":"the","start":29.97},{"text":"flash.","start":30.25}]},{"text":"Strictly, it comes first. From 3 km away, 7 millionths of a second before the light.","show":32.45,"hide":37.65,"words":[{"text":"Strictly,","start":32.45},{"text":"it","start":32.678},{"text":"comes","start":32.905},{"text":"first.","start":33.133},{"text":"From","start":33.36},{"text":"3","start":33.588},{"text":"km","start":33.815},{"text":"away,","start":34.043},{"text":"7","start":34.27},{"text":"millionths","start":34.498},{"text":"of","start":34.725},{"text":"a","start":34.953},{"text":"second","start":35.18},{"text":"before","start":35.408},{"text":"the","start":35.635},{"text":"light.","start":35.863}]}]},{"id":"rule","n":4,"section":1,"title":false,"first":38.65,"end":50.45,"caps":[{"text":"Nothing can carry a signal faster than light. Air would have to be 7 million times stiffer than steel.","show":38.65,"hide":44.05,"words":[{"text":"Nothing","start":38.65},{"text":"can","start":38.849},{"text":"carry","start":39.048},{"text":"a","start":39.247},{"text":"signal","start":39.446},{"text":"faster","start":39.645},{"text":"than","start":39.844},{"text":"light.","start":40.043},{"text":"Air","start":40.242},{"text":"would","start":40.441},{"text":"have","start":40.639},{"text":"to","start":40.838},{"text":"be","start":41.037},{"text":"7","start":41.236},{"text":"million","start":41.435},{"text":"times","start":41.634},{"text":"stiffer","start":41.833},{"text":"than","start":42.032},{"text":"steel.","start":42.231}]},{"text":"Here, only sound's speed changes. How loud things are, and how far they carry, stay the same.","show":45.05,"hide":50.45,"words":[{"text":"Here,","start":45.05},{"text":"only","start":45.272},{"text":"sound's","start":45.495},{"text":"speed","start":45.717},{"text":"changes.","start":45.939},{"text":"How","start":46.162},{"text":"loud","start":46.384},{"text":"things","start":46.606},{"text":"are,","start":46.829},{"text":"and","start":47.051},{"text":"how","start":47.274},{"text":"far","start":47.496},{"text":"they","start":47.718},{"text":"carry,","start":47.941},{"text":"stay","start":48.163},{"text":"the","start":48.385},{"text":"same.","start":48.608}]}]},{"id":"rumble","n":5,"section":1,"title":false,"first":52.65,"end":67.3,"caps":[{"text":"A lightning bolt is kilometres long. It rumbles because its far end is heard late.","show":52.65,"hide":57.75,"words":[{"text":"A","start":52.65},{"text":"lightning","start":52.888},{"text":"bolt","start":53.126},{"text":"is","start":53.364},{"text":"kilometres","start":53.602},{"text":"long.","start":53.84},{"text":"It","start":54.078},{"text":"rumbles","start":54.316},{"text":"because","start":54.554},{"text":"its","start":54.792},{"text":"far","start":55.03},{"text":"end","start":55.268},{"text":"is","start":55.506},{"text":"heard","start":55.744},{"text":"late.","start":55.982}]},{"text":"That one was 6 km long. Its thunder used to roll on for 13 seconds.","show":58.95,"hide":63.3,"words":[{"text":"That","start":58.95},{"text":"one","start":59.153},{"text":"was","start":59.356},{"text":"6","start":59.559},{"text":"km","start":59.762},{"text":"long.","start":59.965},{"text":"Its","start":60.168},{"text":"thunder","start":60.371},{"text":"used","start":60.574},{"text":"to","start":60.777},{"text":"roll","start":60.98},{"text":"on","start":61.183},{"text":"for","start":61.386},{"text":"13","start":61.589},{"text":"seconds.","start":61.792}]},{"text":"Now all of it lands at once.","show":64.9,"hide":67.3,"words":[{"text":"Now","start":64.9},{"text":"all","start":65.14},{"text":"of","start":65.38},{"text":"it","start":65.62},{"text":"lands","start":65.86},{"text":"at","start":66.1},{"text":"once.","start":66.34}]}]},{"id":"call","n":6,"section":1,"title":false,"first":68.9,"end":79.05,"caps":[{"text":"Maisie isn't back. You call her name. The barn should throw it back to you.","show":68.9,"hide":73.65,"words":[{"text":"Maisie","start":68.9},{"text":"isn't","start":69.122},{"text":"back.","start":69.343},{"text":"You","start":69.565},{"text":"call","start":69.787},{"text":"her","start":70.008},{"text":"name.","start":70.23},{"text":"The","start":70.452},{"text":"barn","start":70.673},{"text":"should","start":70.895},{"text":"throw","start":71.117},{"text":"it","start":71.338},{"text":"back","start":71.56},{"text":"to","start":71.782},{"text":"you.","start":72.003}]},{"text":"No echo. Every echo now arrives with your voice.","show":75.65,"hide":79.05,"words":[{"text":"No","start":75.65},{"text":"echo.","start":75.914},{"text":"Every","start":76.179},{"text":"echo","start":76.443},{"text":"now","start":76.708},{"text":"arrives","start":76.972},{"text":"with","start":77.237},{"text":"your","start":77.501},{"text":"voice.","start":77.766}]}]},{"id":"answer","n":7,"section":1,"title":false,"first":81.05,"end":88.4,"caps":[{"text":"She's calling back. You can hear her perfectly.","show":81.05,"hide":84.4,"words":[{"text":"She's","start":81.05},{"text":"calling","start":81.343},{"text":"back.","start":81.636},{"text":"You","start":81.929},{"text":"can","start":82.223},{"text":"hear","start":82.516},{"text":"her","start":82.809},{"text":"perfectly.","start":83.102}]},{"text":"You can't tell where she is.","show":86,"hide":88.4,"words":[{"text":"You","start":86},{"text":"can't","start":86.28},{"text":"tell","start":86.56},{"text":"where","start":86.84},{"text":"she","start":87.12},{"text":"is.","start":87.4}]}]},{"id":"ears","n":8,"section":1,"title":false,"first":89.6,"end":108,"caps":[{"text":"Your brain finds a sound by the gap between your two ears: up to 0.66 thousandths of a second.","show":89.6,"hide":95,"words":[{"text":"Your","start":89.6},{"text":"brain","start":89.799},{"text":"finds","start":89.998},{"text":"a","start":90.197},{"text":"sound","start":90.396},{"text":"by","start":90.595},{"text":"the","start":90.794},{"text":"gap","start":90.993},{"text":"between","start":91.192},{"text":"your","start":91.391},{"text":"two","start":91.589},{"text":"ears:","start":91.788},{"text":"up","start":91.987},{"text":"to","start":92.186},{"text":"0.66","start":92.385},{"text":"thousandths","start":92.584},{"text":"of","start":92.783},{"text":"a","start":92.982},{"text":"second.","start":93.181}]},{"text":"Now it's 0.2 billionths. The smallest gap your brain can use is 44,000 times longer.","show":96.2,"hide":101.4,"words":[{"text":"Now","start":96.2},{"text":"it's","start":96.443},{"text":"0.2","start":96.685},{"text":"billionths.","start":96.928},{"text":"The","start":97.171},{"text":"smallest","start":97.413},{"text":"gap","start":97.656},{"text":"your","start":97.899},{"text":"brain","start":98.141},{"text":"can","start":98.384},{"text":"use","start":98.627},{"text":"is","start":98.869},{"text":"44,000","start":99.112},{"text":"times","start":99.355},{"text":"longer.","start":99.597}]},{"text":"Her voice's waves are now 3,300 km long. Nothing casts a sound shadow. Not even your head.","show":102.6,"hide":108,"words":[{"text":"Her","start":102.6},{"text":"voice's","start":102.822},{"text":"waves","start":103.045},{"text":"are","start":103.267},{"text":"now","start":103.489},{"text":"3,300","start":103.712},{"text":"km","start":103.934},{"text":"long.","start":104.156},{"text":"Nothing","start":104.379},{"text":"casts","start":104.601},{"text":"a","start":104.824},{"text":"sound","start":105.046},{"text":"shadow.","start":105.268},{"text":"Not","start":105.491},{"text":"even","start":105.713},{"text":"your","start":105.935},{"text":"head.","start":106.158}]}]},{"id":"head","n":9,"section":1,"title":false,"first":109.6,"end":122.6,"caps":[{"text":"Every sound now seems to come from inside your head.","show":109.6,"hide":113.2,"words":[{"text":"Every","start":109.6},{"text":"sound","start":109.852},{"text":"now","start":110.104},{"text":"seems","start":110.356},{"text":"to","start":110.608},{"text":"come","start":110.86},{"text":"from","start":111.112},{"text":"inside","start":111.364},{"text":"your","start":111.616},{"text":"head.","start":111.868}]},{"text":"Louder means closer. That's all you have left.","show":114.6,"hide":117.9,"words":[{"text":"Louder","start":114.6},{"text":"means","start":114.889},{"text":"closer.","start":115.178},{"text":"That's","start":115.466},{"text":"all","start":115.755},{"text":"you","start":116.044},{"text":"have","start":116.333},{"text":"left.","start":116.621}]},{"text":"You walk along the corn. She gets quieter.","show":119.5,"hide":122.6,"words":[{"text":"You","start":119.5},{"text":"walk","start":119.771},{"text":"along","start":120.043},{"text":"the","start":120.314},{"text":"corn.","start":120.585},{"text":"She","start":120.856},{"text":"gets","start":121.128},{"text":"quieter.","start":121.399}]}]},{"id":"far","n":10,"section":1,"title":false,"first":124.2,"end":142.05,"caps":[{"text":"Distance doesn't make a sound late any more. A freight train blows its horn 11 km away.","show":124.2,"hide":129.55,"words":[{"text":"Distance","start":124.2},{"text":"doesn't","start":124.42},{"text":"make","start":124.641},{"text":"a","start":124.861},{"text":"sound","start":125.081},{"text":"late","start":125.301},{"text":"any","start":125.522},{"text":"more.","start":125.742},{"text":"A","start":125.962},{"text":"freight","start":126.183},{"text":"train","start":126.403},{"text":"blows","start":126.623},{"text":"its","start":126.844},{"text":"horn","start":127.064},{"text":"11","start":127.284},{"text":"km","start":127.504},{"text":"away.","start":127.725}]},{"text":"You hear it at the same instant as the Hansens' dogs, 1.4 km away.","show":130.95,"hide":135.25,"words":[{"text":"You","start":130.95},{"text":"hear","start":131.165},{"text":"it","start":131.38},{"text":"at","start":131.595},{"text":"the","start":131.81},{"text":"same","start":132.025},{"text":"instant","start":132.24},{"text":"as","start":132.455},{"text":"the","start":132.67},{"text":"Hansens'","start":132.885},{"text":"dogs,","start":133.1},{"text":"1.4","start":133.315},{"text":"km","start":133.53},{"text":"away.","start":133.745}]},{"text":"Everything for kilometres around, all at once, inside your head. Somewhere in it is her voice.","show":136.65,"hide":142.05,"words":[{"text":"Everything","start":136.65},{"text":"for","start":136.886},{"text":"kilometres","start":137.123},{"text":"around,","start":137.359},{"text":"all","start":137.595},{"text":"at","start":137.831},{"text":"once,","start":138.068},{"text":"inside","start":138.304},{"text":"your","start":138.54},{"text":"head.","start":138.776},{"text":"Somewhere","start":139.013},{"text":"in","start":139.249},{"text":"it","start":139.485},{"text":"is","start":139.721},{"text":"her","start":139.958},{"text":"voice.","start":140.194}]}]},{"id":"siren","n":11,"section":2,"title":false,"first":144.25,"end":160.05,"caps":[{"text":"The tornado sirens in town, 6 km away. You can't tell which way the town is.","show":144.25,"hide":149.05,"words":[{"text":"The","start":144.25},{"text":"tornado","start":144.46},{"text":"sirens","start":144.67},{"text":"in","start":144.88},{"text":"town,","start":145.09},{"text":"6","start":145.3},{"text":"km","start":145.51},{"text":"away.","start":145.72},{"text":"You","start":145.93},{"text":"can't","start":146.14},{"text":"tell","start":146.35},{"text":"which","start":146.56},{"text":"way","start":146.77},{"text":"the","start":146.98},{"text":"town","start":147.19},{"text":"is.","start":147.4}]},{"text":"A sheriff's car. Its siren should drop in pitch as it passes. It doesn't.","show":151.05,"hide":155.7,"words":[{"text":"A","start":151.05},{"text":"sheriff's","start":151.283},{"text":"car.","start":151.515},{"text":"Its","start":151.748},{"text":"siren","start":151.98},{"text":"should","start":152.213},{"text":"drop","start":152.445},{"text":"in","start":152.678},{"text":"pitch","start":152.91},{"text":"as","start":153.143},{"text":"it","start":153.375},{"text":"passes.","start":153.608},{"text":"It","start":153.84},{"text":"doesn't.","start":154.073}]},{"text":"You can't tell if it's coming or going.","show":157.1,"hide":160.05,"words":[{"text":"You","start":157.1},{"text":"can't","start":157.358},{"text":"tell","start":157.616},{"text":"if","start":157.874},{"text":"it's","start":158.133},{"text":"coming","start":158.391},{"text":"or","start":158.649},{"text":"going.","start":158.907}]}]},{"id":"tornado","n":12,"section":2,"title":false,"first":162.65,"end":175.1,"caps":[{"text":"In the flash: a tornado, 3 km west.","show":162.65,"hide":165.4,"words":[{"text":"In","start":162.65},{"text":"the","start":162.891},{"text":"flash:","start":163.131},{"text":"a","start":163.372},{"text":"tornado,","start":163.613},{"text":"3","start":163.853},{"text":"km","start":164.094},{"text":"west.","start":164.334}]},{"text":"Its roar is already here. It sounds as close as the rain.","show":166.6,"hide":170.45,"words":[{"text":"Its","start":166.6},{"text":"roar","start":166.825},{"text":"is","start":167.049},{"text":"already","start":167.274},{"text":"here.","start":167.498},{"text":"It","start":167.723},{"text":"sounds","start":167.948},{"text":"as","start":168.172},{"text":"close","start":168.397},{"text":"as","start":168.621},{"text":"the","start":168.846},{"text":"rain.","start":169.07}]},{"text":"It's getting louder. That's all you know.","show":172.05,"hide":175.1,"words":[{"text":"It's","start":172.05},{"text":"getting","start":172.355},{"text":"louder.","start":172.66},{"text":"That's","start":172.965},{"text":"all","start":173.27},{"text":"you","start":173.575},{"text":"know.","start":173.88}]}]},{"id":"phone","n":13,"section":3,"title":false,"first":176.7,"end":195.15,"caps":[{"text":"You call her phone. It rings as if it were in your own pocket.","show":176.7,"hide":180.8,"words":[{"text":"You","start":176.7},{"text":"call","start":176.905},{"text":"her","start":177.11},{"text":"phone.","start":177.315},{"text":"It","start":177.52},{"text":"rings","start":177.725},{"text":"as","start":177.93},{"text":"if","start":178.135},{"text":"it","start":178.34},{"text":"were","start":178.545},{"text":"in","start":178.75},{"text":"your","start":178.955},{"text":"own","start":179.16},{"text":"pocket.","start":179.365}]},{"text":"She answers. Through the air, her voice now beats the phone to you.","show":182.6,"hide":186.95,"words":[{"text":"She","start":182.6},{"text":"answers.","start":182.834},{"text":"Through","start":183.068},{"text":"the","start":183.303},{"text":"air,","start":183.537},{"text":"her","start":183.771},{"text":"voice","start":184.005},{"text":"now","start":184.24},{"text":"beats","start":184.474},{"text":"the","start":184.708},{"text":"phone","start":184.942},{"text":"to","start":185.177},{"text":"you.","start":185.411}]},{"text":"Her phone says she's 120 metres into the corn.","show":188.35,"hide":191.65,"words":[{"text":"Her","start":188.35},{"text":"phone","start":188.607},{"text":"says","start":188.863},{"text":"she's","start":189.12},{"text":"120","start":189.377},{"text":"metres","start":189.633},{"text":"into","start":189.89},{"text":"the","start":190.147},{"text":"corn.","start":190.403}]},{"text":"West. Towards the tornado.","show":192.85,"hide":195.15,"words":[{"text":"West.","start":192.85},{"text":"Towards","start":193.253},{"text":"the","start":193.655},{"text":"tornado.","start":194.058}]}]},{"id":"corn","n":14,"section":3,"title":false,"first":196.95,"end":213.55,"caps":[{"text":"You run into the corn. It's 2.4 metres tall. Your torch shows you one row at a time.","show":196.95,"hide":202.15,"words":[{"text":"You","start":196.95},{"text":"run","start":197.152},{"text":"into","start":197.354},{"text":"the","start":197.557},{"text":"corn.","start":197.759},{"text":"It's","start":197.961},{"text":"2.4","start":198.163},{"text":"metres","start":198.366},{"text":"tall.","start":198.568},{"text":"Your","start":198.77},{"text":"torch","start":198.972},{"text":"shows","start":199.174},{"text":"you","start":199.377},{"text":"one","start":199.579},{"text":"row","start":199.781},{"text":"at","start":199.983},{"text":"a","start":200.186},{"text":"time.","start":200.388}]},{"text":"Beyond it, you only see when the lightning strikes.","show":203.95,"hide":207.5,"words":[{"text":"Beyond","start":203.95},{"text":"it,","start":204.226},{"text":"you","start":204.502},{"text":"only","start":204.778},{"text":"see","start":205.054},{"text":"when","start":205.331},{"text":"the","start":205.607},{"text":"lightning","start":205.883},{"text":"strikes.","start":206.159}]},{"text":"She sounds like she's right beside you. She's 90 metres away.","show":209.5,"hide":213.55,"words":[{"text":"She","start":209.5},{"text":"sounds","start":209.758},{"text":"like","start":210.015},{"text":"she's","start":210.273},{"text":"right","start":210.531},{"text":"beside","start":210.789},{"text":"you.","start":211.046},{"text":"She's","start":211.304},{"text":"90","start":211.562},{"text":"metres","start":211.82},{"text":"away.","start":212.077}]}]},{"id":"strike","n":15,"section":3,"title":false,"first":215.35,"end":227.55,"caps":[{"text":"Lightning hits the yard light behind you.","show":215.35,"hide":218.4,"words":[{"text":"Lightning","start":215.35},{"text":"hits","start":215.655},{"text":"the","start":215.96},{"text":"yard","start":216.265},{"text":"light","start":216.57},{"text":"behind","start":216.875},{"text":"you.","start":217.18}]},{"text":"You used to get a quarter of a second between the flash and the bang.","show":219.6,"hide":224.05,"words":[{"text":"You","start":219.6},{"text":"used","start":219.808},{"text":"to","start":220.015},{"text":"get","start":220.223},{"text":"a","start":220.431},{"text":"quarter","start":220.638},{"text":"of","start":220.846},{"text":"a","start":221.054},{"text":"second","start":221.261},{"text":"between","start":221.469},{"text":"the","start":221.677},{"text":"flash","start":221.884},{"text":"and","start":222.092},{"text":"the","start":222.3},{"text":"bang.","start":222.507}]},{"text":"Now the bang is the flash.","show":225.25,"hide":227.55,"words":[{"text":"Now","start":225.25},{"text":"the","start":225.518},{"text":"bang","start":225.787},{"text":"is","start":226.055},{"text":"the","start":226.323},{"text":"flash.","start":226.592}]}]},{"id":"wind","n":16,"section":3,"title":false,"first":229.35,"end":238.05,"caps":[{"text":"The wind is rushing in towards the tornado at 90 km/h.","show":229.35,"hide":233.05,"words":[{"text":"The","start":229.35},{"text":"wind","start":229.585},{"text":"is","start":229.821},{"text":"rushing","start":230.056},{"text":"in","start":230.292},{"text":"towards","start":230.527},{"text":"the","start":230.763},{"text":"tornado","start":230.998},{"text":"at","start":231.234},{"text":"90","start":231.469},{"text":"km/h.","start":231.705}]},{"text":"The corn is lying down. All of it pointing west.","show":234.65,"hide":238.05,"words":[{"text":"The","start":234.65},{"text":"corn","start":234.888},{"text":"is","start":235.126},{"text":"lying","start":235.364},{"text":"down.","start":235.602},{"text":"All","start":235.84},{"text":"of","start":236.078},{"text":"it","start":236.316},{"text":"pointing","start":236.554},{"text":"west.","start":236.792}]}]},{"id":"neighbour","n":17,"section":3,"title":false,"first":240.25,"end":250.55,"caps":[{"text":"The Hansen farm, 1.3 km west. The tornado is on it.","show":240.25,"hide":243.8,"words":[{"text":"The","start":240.25},{"text":"Hansen","start":240.476},{"text":"farm,","start":240.702},{"text":"1.3","start":240.928},{"text":"km","start":241.154},{"text":"west.","start":241.38},{"text":"The","start":241.605},{"text":"tornado","start":241.831},{"text":"is","start":242.057},{"text":"on","start":242.283},{"text":"it.","start":242.509}]},{"text":"You hear its roof go. You can't tell if that was a kilometre away, or a hundred metres.","show":245.2,"hide":250.55,"words":[{"text":"You","start":245.2},{"text":"hear","start":245.408},{"text":"its","start":245.616},{"text":"roof","start":245.824},{"text":"go.","start":246.032},{"text":"You","start":246.24},{"text":"can't","start":246.448},{"text":"tell","start":246.656},{"text":"if","start":246.864},{"text":"that","start":247.073},{"text":"was","start":247.281},{"text":"a","start":247.489},{"text":"kilometre","start":247.697},{"text":"away,","start":247.905},{"text":"or","start":248.113},{"text":"a","start":248.321},{"text":"hundred","start":248.529},{"text":"metres.","start":248.737}]}]},{"id":"found","n":18,"section":3,"title":false,"first":251.85,"end":258.65,"caps":[{"text":"A flash. A yellow raincoat, 6 metres away.","show":251.85,"hide":254.95,"words":[{"text":"A","start":251.85},{"text":"flash.","start":252.121},{"text":"A","start":252.392},{"text":"yellow","start":252.664},{"text":"raincoat,","start":252.935},{"text":"6","start":253.206},{"text":"metres","start":253.478},{"text":"away.","start":253.749}]},{"text":"She's holding the dog.","show":256.55,"hide":258.65,"words":[{"text":"She's","start":256.55},{"text":"holding","start":256.918},{"text":"the","start":257.285},{"text":"dog.","start":257.653}]}]},{"id":"back","n":19,"section":3,"title":false,"first":260.25,"end":273.7,"caps":[{"text":"The storm cellar is 130 metres behind you. The tornado is less than a kilometre away.","show":260.25,"hide":265.5,"words":[{"text":"The","start":260.25},{"text":"storm","start":260.48},{"text":"cellar","start":260.709},{"text":"is","start":260.939},{"text":"130","start":261.169},{"text":"metres","start":261.398},{"text":"behind","start":261.628},{"text":"you.","start":261.858},{"text":"The","start":262.087},{"text":"tornado","start":262.317},{"text":"is","start":262.547},{"text":"less","start":262.777},{"text":"than","start":263.006},{"text":"a","start":263.236},{"text":"kilometre","start":263.466},{"text":"away.","start":263.695}]},{"text":"You can hear it everywhere.","show":267.1,"hide":269.45,"words":[{"text":"You","start":267.1},{"text":"can","start":267.429},{"text":"hear","start":267.758},{"text":"it","start":268.087},{"text":"everywhere.","start":268.416}]},{"text":"You can't hear which way it's moving.","show":270.85,"hide":273.7,"words":[{"text":"You","start":270.85},{"text":"can't","start":271.135},{"text":"hear","start":271.42},{"text":"which","start":271.705},{"text":"way","start":271.99},{"text":"it's","start":272.275},{"text":"moving.","start":272.56}]}]},{"id":"question","n":20,"section":3,"title":false,"first":275.3,"end":279.1,"caps":[{"text":"Which way would you run?","show":275.3,"hide":279.1,"words":[{"text":"Which","start":275.3},{"text":"way","start":275.608},{"text":"would","start":275.916},{"text":"you","start":276.224},{"text":"run?","start":276.532}]}]}]};
